  const parts = []
  chars.forEach((char, index) => {
    if (index > 0) parts.push({ key: `sep-${index}`, text: '·', className: 'gz-sep' })
    const part = makeGanzhiParts(char)[0]
    parts.push(Object.assign({}, part, { key: `hidden-${index}-${char}` }))
  })
