defs["utils/share.js"] = function (module, exports, require) {
const SHARE_FLAG = '1'

const INDEX_PATH = '/pages/index/index'

function encodeShare(value) {
  return encodeURIComponent(value == null ? '' : String(value))
}

function decodeShare(value) {
  try { return decodeURIComponent(value || '') } catch (e) { return value || '' }
}

function buildSharePath(params) {
  const safeParams = params || {}
  const query = Object.keys(safeParams)
    .filter(key => safeParams[key] !== undefined && safeParams[key] !== null && safeParams[key] !== '')
    .map(key => `${encodeURIComponent(key)}=${encodeShare(safeParams[key])}`)
    .join('&')
  return `${INDEX_PATH}${query ? '?' + query : ''}`
}

function parseShareNumbers(value) {
  return String(value || '').split(/[,.]/).map(Number).filter(n => Number.isFinite(n))
}

function parseShareOverrides(options, branches) {
  const zhi = branches || []
  const mg = decodeShare(options && options.mg)
  const hb = decodeShare(options && options.hb)
  const nm = decodeShare(options && options.nm)
  return {
    monthGeneral: zhi.indexOf(mg) >= 0 ? mg : null,
    hourBranch: zhi.indexOf(hb) >= 0 ? hb : null,
    nobleMode: nm === 'day' || nm === 'night' ? nm : null,
  }
}

module.exports = {
  SHARE_FLAG,
  INDEX_PATH,
  encodeShare,
  decodeShare,
  buildSharePath,
  parseShareNumbers,
  parseShareOverrides,
}

}
defs["utils/season-share.js"] = function (module, exports, require) {
// 时令分享图：与 iOS 版 SeasonShareCard 同一版式。固定宽度 380，按 3 倍分辨率绘制。
// 跟随系统外观：深色模式下出深色底、浅色字的图（model.dark），配色与页面的深色模式一致。
// 只负责在 Canvas 2D 上画，取图和分享在页面里做。

const WIDTH = 380
const PAD = 30
// 宋体字按字形轮廓画出来（见 canvas-text.js），不依赖画布上的字体注册
const { setFont, measureText, fillText } = require('./canvas-text.js')

const PALETTES = {
  light: {
    paper: '#F5F4F1', ink: '#121211', subtle: '#7C7B76', hairline: '#E3E1DB',
    glass: 'rgba(255,255,255,0.58)', glassEdge: 'rgba(255,255,255,0.85)', shadow: 'rgba(18,18,17,0.07)',
    gold: '#B3903F', wood: '#5E8C6A', water: '#4E7A9B', fire: '#C25B45', earth: '#8F7658',
  },
  dark: {
    paper: '#0E0E0D', ink: '#F2F1EE', subtle: '#8D8C87', hairline: '#2B2B29',
    glass: 'rgba(34,34,32,0.58)', glassEdge: 'rgba(255,255,255,0.08)', shadow: 'rgba(0,0,0,0.3)',
    gold: '#D0B06B', wood: '#8DBB99', water: '#82AACB', fire: '#E3806A', earth: '#B59C7C',
  },
}

// 当前配色。两张图的绘制代码都直接读这两个对象，画之前用 usePalette 切换
const COLORS = {}
const ELEMENT_COLORS = {}

function usePalette(dark) {
  const p = dark ? PALETTES.dark : PALETTES.light
  Object.assign(COLORS, {
    paper: p.paper, ink: p.ink, subtle: p.subtle, hairline: p.hairline,
    glass: p.glass, glassEdge: p.glassEdge, shadow: p.shadow, dark: !!dark,
  })
  Object.assign(ELEMENT_COLORS, {
    'gz-gold': p.gold, 'gz-wood': p.wood, 'gz-water': p.water, 'gz-fire': p.fire, 'gz-earth': p.earth,
  })
}
usePalette(false)

function rgba(hex, alpha) {
  const n = parseInt(hex.slice(1), 16)
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${alpha})`
}

// 底色 + 几团很淡的主题色光晕（对应 iOS 的 MeshGradient）。分享图和结果导出图共用，背景始终一致。
// 默认黑色主题下用黑色晕染会显得脏，改用与页面背景游光相同的几种浅色
// 与页面背景同一组游光（位置、大小照 index.wxss 的 .light-0..4：直径 130vw 的圆、边缘渐隐），
// glows 是五团游光的颜色（utils/ambient.js）。没有传 glows 时用下面的旧画法
function drawAmbient(ctx, fw, fh, glows) {
  const vw = fw / 100
  const vh = fh / 100
  const r = 65 * vw
  const centers = [
    [10 * vw, 35 * vw],
    [fw - 5 * vw, 20 * vh + 65 * vw],
    [25 * vw, fh - 25 * vw],
    [fw - 20 * vw, fh - 10 * vh - 65 * vw],
    [65 * vw, 35 * vh + 65 * vw],
  ]
  centers.forEach(([x, y], i) => {
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, glows[i])
    g.addColorStop(1, glows[i].replace(/[\d.]+\)$/, '0)'))
    ctx.fillStyle = g
    ctx.fillRect(0, 0, fw, fh)
  })
}

function drawBackdrop(ctx, fw, fh, accent, glows) {
  ctx.fillStyle = COLORS.paper
  ctx.fillRect(0, 0, fw, fh)
  if (glows && glows.length >= 5) { drawAmbient(ctx, fw, fh, glows); return }
  // 光晕大小按宽度算：长图不会被整片染色，只在上、中、下几处带一点颜色
  const glow = (gx, gy, r, a, tint = accent) => {
    const g = ctx.createRadialGradient(gx, gy, 0, gx, gy, r)
    g.addColorStop(0, rgba(tint, a))
    g.addColorStop(1, rgba(tint, 0))
    ctx.fillStyle = g
    ctx.fillRect(0, 0, fw, fh)
  }
  // 深色底上光晕要更淡，与页面深色模式的游光浓度（16%，浅色为 30%）同比例
  const k = COLORS.dark ? 0.55 : 1
  if (accent.toUpperCase() === PALETTES.light.ink || accent.toUpperCase() === PALETTES.dark.ink) {
    // 浓度与页面背景游光相同，只是淡淡一层
    glow(fw, 0, fw * 0.8, 0.3 * k, '#C7E4FF')
    glow(fw * 0.62, fh * 0.45, fw * 0.65, 0.24 * k, '#E3C7FF')
    glow(0, fh, fw * 0.75, 0.3 * k, '#FFE6C7')
  } else {
    glow(fw, 0, fw * 0.7, 0.08 * (COLORS.dark ? 1.4 : 1))
    glow(fw * 0.62, fh * 0.45, fw * 0.55, 0.12 * (COLORS.dark ? 1.4 : 1))
    glow(0, fh, fw * 0.6, 0.06 * (COLORS.dark ? 1.4 : 1))
  }
}

// 一张卡片：与页面上的玻璃卡片同一样式——半透明白底、细白边、一层很淡的投影、大圆角
function drawPanel(ctx, x, y, w, h, r = 20) {
  const path = () => {
    ctx.beginPath()
    ctx.moveTo(x + r, y)
    ctx.arcTo(x + w, y, x + w, y + h, r)
    ctx.arcTo(x + w, y + h, x, y + h, r)
    ctx.arcTo(x, y + h, x, y, r)
    ctx.arcTo(x, y, x + w, y, r)
    ctx.closePath()
  }
  ctx.save()
  ctx.shadowColor = COLORS.shadow
  ctx.shadowBlur = 18
  ctx.shadowOffsetY = 6
  ctx.fillStyle = COLORS.glass
  path()
  ctx.fill()
  ctx.restore()
  ctx.save()
  ctx.strokeStyle = COLORS.glassEdge
  ctx.lineWidth = 0.8
  path()
  ctx.stroke()
  ctx.restore()
}

// 宽字距的小标签：逐字绘制，字距 tracking
function drawTracked(ctx, text, x, y, tracking, align = 'left') {
  const chars = String(text).split('')
  const widths = chars.map(c => measureText(ctx, c))
  const total = widths.reduce((a, b) => a + b, 0) + tracking * Math.max(0, chars.length - 1)
  let cx = align === 'right' ? x - total : align === 'center' ? x - total / 2 : x
  ctx.textAlign = 'left'
  chars.forEach((c, i) => {
    fillText(ctx, c, cx, y)
    cx += widths[i] + tracking
  })
  return total
}

// 一柱干支：每个字下面一枚五行圆点（或按设置改为字色 / 单色）
function drawPillar(ctx, parts, cx, top, size, elementStyle) {
  // 圆点半径约为字号的 16%，与结果导出图一致
  const dotR = size * 0.16
  setFont(ctx, size, 700)
  const gap = 2
  const widths = parts.map(p => measureText(ctx, p.text))
  const total = widths.reduce((a, b) => a + b, 0) + gap * Math.max(0, parts.length - 1)
  let x = cx - total / 2
  ctx.textBaseline = 'top'
  parts.forEach((p, i) => {
    const tone = ELEMENT_COLORS[p.className]
    ctx.fillStyle = elementStyle === 'text' && tone ? tone : COLORS.ink
    fillText(ctx, p.text, x, top)
    if (elementStyle === 'dot' && tone) {
      ctx.fillStyle = tone
      ctx.beginPath()
      ctx.arc(x + widths[i] / 2, top + size * 1.18 + dotR + 1, dotR, 0, Math.PI * 2)
      ctx.fill()
    }
    x += widths[i] + gap
  })
  return elementStyle === 'dot' ? size * 1.18 + dotR * 2 + 2 : size * 1.18
}

// 模糊字形的替身：每个字一团灰色径向渐变，下面藏干行一条更淡的
function drawVeil(ctx, cx, top, count, size) {
  const blob = (x, y, rx, ry, a) => {
    ctx.save()
    ctx.translate(x, y)
    ctx.scale(1, ry / rx)
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, rx)
    g.addColorStop(0, rgba(COLORS.subtle, a))
    g.addColorStop(1, rgba(COLORS.subtle, 0))
    ctx.fillStyle = g
    ctx.fillRect(-rx, -rx, rx * 2, rx * 2)
    ctx.restore()
  }
  const step = size + 2
  for (let i = 0; i < count; i++) {
    blob(cx + (i - (count - 1) / 2) * step, top + size * 0.55, size * 0.75, size * 0.7, 0.22)
  }
  blob(cx, top + size * 1.18 + 10 + 22, size * 1.1, 12, 0.1)
}

// “不看”的眼睛图标（与页面上隐去时柱时的图标一致）
function drawEyeOff(ctx, cx, cy, s) {
  ctx.save()
  ctx.strokeStyle = COLORS.subtle
  ctx.lineWidth = 1.4
  ctx.lineCap = 'round'
  ctx.beginPath()
  ctx.moveTo(cx - s, cy)
  ctx.quadraticCurveTo(cx, cy - s * 1.15, cx + s, cy)
  ctx.quadraticCurveTo(cx, cy + s * 1.15, cx - s, cy)
  ctx.stroke()
  ctx.beginPath()
  ctx.arc(cx, cy, s * 0.32, 0, Math.PI * 2)
  ctx.stroke()
  ctx.beginPath()
  ctx.moveTo(cx - s * 0.85, cy + s * 0.85)
  ctx.lineTo(cx + s * 0.85, cy - s * 0.85)
  ctx.stroke()
  ctx.restore()
}

// 先按内容排出高度，再画
function measureHeight(model) {
  let y = PAD
  y += 14            // SEASONS 行
  y += 16 + 50       // 日期
  y += 6 + 18        // 星期、农历
  y += 22 + 2        // 短横线
  y += 30 + 110 + 14 // 四柱（放在一张卡片里，下边留 14）
  if (model.trueSolar) y += 14 + 14  // 真太阳时紧贴在四柱卡片下面
  y += (model.trueSolar ? 20 : 30) + 12  // 落款
  return y + PAD
}

// 转发卡片的图片按 5:4 显示，其他比例会被裁掉；这里给出能完整放下卡片的 5:4 画幅
function shareFrame(model) {
  const height = measureHeight(model)
  const width = Math.max(WIDTH, Math.ceil(height * 1.25))
  return { width, height: Math.ceil(width / 1.25) }
}

// frame：整张画布的尺寸。比卡片宽时内容居中，底色和光晕铺满整张画布，不会出现接缝
function drawSeasonCard(ctx, model, frame) {
  usePalette(model.dark)
  const height = measureHeight(model)
  const accent = model.accent
  const fw = frame ? frame.width : WIDTH
  const fh = frame ? frame.height : height

  drawBackdrop(ctx, fw, fh, accent, model.glows)

  ctx.save()
  ctx.translate((fw - WIDTH) / 2, (fh - height) / 2)
  let y = PAD
  ctx.textBaseline = 'top'

  setFont(ctx, 10, 700)
  // 文字一律墨色或灰色；主题色只给短横线、五行圆点这类图形
  ctx.fillStyle = COLORS.subtle
  drawTracked(ctx, 'SEASONS', PAD, y + 2, 2)
  setFont(ctx, 11, 500)
  ctx.fillStyle = COLORS.subtle
  ctx.textAlign = 'right'
  fillText(ctx, model.termLine, WIDTH - PAD, y + 1)
  ctx.textAlign = 'left'
  y += 14

  y += 16
  setFont(ctx, 42, 700)
  ctx.fillStyle = COLORS.ink
  fillText(ctx, model.dateText, PAD, y)
  y += 50

  y += 6
  setFont(ctx, 14)
  ctx.fillStyle = COLORS.subtle
  fillText(ctx, model.subtitle, PAD, y)
  y += 18

  y += 22
  ctx.fillStyle = rgba(accent, 0.75)
  ctx.fillRect(PAD, y, 32, 2)
  y += 2

  // 四柱：放在一张卡片里，细线分栏
  y += 30
  drawPanel(ctx, PAD - 12, y - 14, WIDTH - PAD * 2 + 24, 110 + 28)
  const colW = (WIDTH - PAD * 2) / 4
  model.pillars.forEach((p, i) => {
    const cx = PAD + colW * i + colW / 2
    if (i > 0) {
      ctx.fillStyle = COLORS.hairline
      ctx.fillRect(PAD + colW * i, y + 4, 0.5, 104)
    }
    setFont(ctx, 10, 500)
    ctx.fillStyle = COLORS.subtle
    ctx.textAlign = 'center'
    fillText(ctx, p.label, cx, y)
    ctx.textAlign = 'left'

    const glyphTop = y + 12 + 12
    if (p.hidden) {
      // 隐去时柱：不画真实的字（手机画布不支持 ctx.filter 模糊，画了就能看清），
      // 用几团柔和的灰色光晕代替模糊后的字形，再盖一枚“不看”图标
      drawVeil(ctx, cx, glyphTop, p.parts.length, 32)
      drawEyeOff(ctx, cx, glyphTop + 34, 10)
      return
    }
    const used = drawPillar(ctx, p.parts, cx, glyphTop, 32, model.elementStyle)
    setFont(ctx, 15, 500)
    ctx.fillStyle = COLORS.subtle
    ctx.textAlign = 'center'
    drawTracked(ctx, p.stems, cx, glyphTop + used + 12, 6, 'center')
  })
  y += 110 + 14

  if (model.trueSolar) {
    y += 14
    setFont(ctx, 12)
    ctx.fillStyle = COLORS.subtle
    fillText(ctx, model.trueSolar, PAD, y)
    y += 14
  }

  // 落款：细线夹一枚居中的字标
  y += model.trueSolar ? 20 : 30
  setFont(ctx, 10, 500)
  ctx.fillStyle = COLORS.subtle
  const markW = drawTracked(ctx, 'PBLOSSOM', WIDTH / 2, y, 2, 'center')
  ctx.fillStyle = COLORS.hairline
  ctx.fillRect(PAD, y + 6, WIDTH / 2 - markW / 2 - 10 - PAD, 0.5)
  ctx.fillRect(WIDTH / 2 + markW / 2 + 10, y + 6, WIDTH / 2 - markW / 2 - 10 - PAD, 0.5)
  ctx.restore()

  return height
}

module.exports = { WIDTH, measureHeight, shareFrame, drawSeasonCard, drawBackdrop, drawPanel, drawVeil, drawEyeOff, usePalette, COLORS, ELEMENT_COLORS }

}
defs["utils/canvas-text.js"] = function (module, exports, require) {
// 分享图上的宋体字：按字形轮廓直接画路径，不依赖 wx.loadFontFace。
// iOS 实测画布用不上注册到 native 的字体，所以把要用的字的轮廓预先导出（scripts/build_miniprogram_font.py），
// 这里解码后用 moveTo / lineTo / quadraticCurveTo 画出来。数据里没有的字退回系统字体。
//
// 用法与画布自带的接口对应：setFont 代替 ctx.font，fillText / measureText 代替同名方法，
// 对齐与基线仍读 ctx.textAlign、ctx.textBaseline。画之前先 await ready()。

// 字形数据随主包一起打包（放进分包后，微信打包时会把只被异步引用的文件当作无用文件去掉，手机上就加载不到）。
// ready() 保留成异步接口，调用方不用关心数据从哪里来
const SOURCES = {
  400: () => require('../assets/fonts/PBlossomGlyphs.js'),
  700: () => require('../assets/fonts/PBlossomGlyphsBold.js'),
}
const fonts = {}
const fontState = new WeakMap()

function ready() {
  try {
    Object.keys(SOURCES).forEach((w) => { if (!fonts[w]) fonts[w] = { data: SOURCES[w](), paths: {} } })
    return Promise.resolve()
  } catch (err) {
    return Promise.reject(err)
  }
}

function glyphFont(weight) {
  return fonts[weight] || null
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const B64_INDEX = {}
for (let i = 0; i < B64.length; i++) B64_INDEX[B64[i]] = i

function decodeBase64(str) {
  const bytes = []
  let buffer = 0
  let bits = 0
  for (let i = 0; i < str.length; i++) {
    const v = B64_INDEX[str[i]]
    if (v === undefined) continue
    buffer = (buffer << 6) | v
    bits += 6
    if (bits >= 8) {
      bits -= 8
      bytes.push((buffer >> bits) & 255)
    }
  }
  return bytes
}

// 解成若干条轮廓，每条是 [x, y, 在曲线上] 的点序列
function decodeContours(b64) {
  const bytes = decodeBase64(b64)
  let pos = 0
  const next = () => {
    let value = 0
    let shift = 0
    let byte
    do {
      byte = bytes[pos++]
      value += (byte & 127) * Math.pow(2, shift)
      shift += 7
    } while (byte & 128)
    return value
  }
  const unzig = (v) => (v % 2 ? -(v + 1) / 2 : v / 2)
  const count = next()
  const sizes = []
  for (let i = 0; i < count; i++) sizes.push(next())
  let x = 0
  let y = 0
  return sizes.map((size) => {
    const points = []
    for (let i = 0; i < size; i++) {
      const vx = next()
      x += unzig(Math.floor(vx / 2))
      y += unzig(next())
      points.push([x, y, vx % 2 === 1])
    }
    return points
  })
}

function glyphPath(font, ch) {
  if (!(ch in font.paths)) {
    const entry = font.data.glyphs[ch]
    font.paths[ch] = entry ? { advance: entry[0], contours: decodeContours(entry[1]) } : null
  }
  return font.paths[ch]
}

// TrueType 轮廓：相邻两个曲线外的控制点之间隐含一个曲线上的点。坐标 y 向上，这里翻成画布的 y 向下
function traceGlyph(ctx, contours, ox, oy, s) {
  contours.forEach((pts) => {
    const n = pts.length
    if (!n) return
    const X = (p) => ox + p[0] * s
    const Y = (p) => oy - p[1] * s
    const mid = (a, b) => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, true]
    let startIndex = pts.findIndex((p) => p[2])
    let start
    if (startIndex < 0) {
      start = mid(pts[0], pts[1 % n])
      startIndex = 1
    } else {
      start = pts[startIndex]
      startIndex += 1
    }
    ctx.moveTo(X(start), Y(start))
    let control = null
    for (let k = 0; k < n; k++) {
      const p = pts[(startIndex + k) % n]
      if (p === start) continue
      if (p[2]) {
        if (control) ctx.quadraticCurveTo(X(control), Y(control), X(p), Y(p))
        else ctx.lineTo(X(p), Y(p))
        control = null
      } else {
        if (control) {
          const m = mid(control, p)
          ctx.quadraticCurveTo(X(control), Y(control), X(m), Y(m))
        }
        control = p
      }
    }
    if (control) ctx.quadraticCurveTo(X(control), Y(control), X(start), Y(start))
    else ctx.lineTo(X(start), Y(start))
    ctx.closePath()
  })
}

// family 不传时用宋体字形；传了（如 'sans-serif'）就是普通的系统字体
function setFont(ctx, size, weight = 400, family) {
  if (family) {
    ctx.font = `${weight >= 600 ? 'bold' : 'normal'} ${size}px ${family}`
    fontState.delete(ctx)
    return
  }
  const w = weight >= 600 ? 700 : 400
  // 数据里没有的字（或字形数据没能加载）退回系统衬线字体
  ctx.font = `${w === 700 ? 'bold' : 'normal'} ${size}px serif`
  const font = glyphFont(w)
  if (font) fontState.set(ctx, { size, font })
  else fontState.delete(ctx)
}

function measureText(ctx, text) {
  const state = fontState.get(ctx)
  if (!state) return ctx.measureText(text).width
  const scale = state.size / state.font.data.upm
  let width = 0
  for (const ch of String(text)) {
    const g = glyphPath(state.font, ch)
    width += g ? g.advance * scale : ctx.measureText(ch).width
  }
  return width
}

function fillText(ctx, text, x, y) {
  const state = fontState.get(ctx)
  if (!state) { ctx.fillText(text, x, y); return }
  const str = String(text)
  const data = state.font.data
  const s = state.size / data.upm
  const width = measureText(ctx, str)
  const align = ctx.textAlign
  let cx = align === 'right' || align === 'end' ? x - width : align === 'center' ? x - width / 2 : x
  // 文字顶端到基线取一个字高：与此前用字体绘制、已经定稿的版式位置一致
  const ascent = state.size
  const baseline = ctx.textBaseline
  let by = y
  if (baseline === 'top' || baseline === 'hanging') by = y + ascent
  else if (baseline === 'middle') by = y + ascent - state.size / 2
  else if (baseline === 'bottom' || baseline === 'ideographic') by = y - (state.size - ascent)

  const fallback = []
  ctx.beginPath()
  for (const ch of str) {
    const g = glyphPath(state.font, ch)
    if (g) {
      traceGlyph(ctx, g.contours, cx, by, s)
      cx += g.advance * s
    } else {
      fallback.push([ch, cx])
      cx += ctx.measureText(ch).width
    }
  }
  ctx.fill()
  if (fallback.length) {
    const saved = ctx.textBaseline
    ctx.textBaseline = 'alphabetic'
    ctx.textAlign = 'left'
    fallback.forEach(([ch, fx]) => ctx.fillText(ch, fx, by))
    ctx.textBaseline = saved
    ctx.textAlign = align
  }
}

module.exports = { ready, setFont, measureText, fillText }

}
