defs["utils/divination.js"] = function (module, exports, require) {
const { formatDate, getCalendarInfo, getHourGanZhi } = require('./calendar.js')
const { HEXAGRAMS_DATA } = require('../data/hexagrams.js')
const { ZHI_ELEMENTS, elementLineClass, makeGanzhiParts } = require('./elements.js')

const HEX_DATA = HEXAGRAMS_DATA
const YAO_TO_NUM = {}

Object.keys(HEX_DATA.trigrams).forEach((key) => {
  const yao = HEX_DATA.trigrams[key].yao
  YAO_TO_NUM[yao.join('-')] = Number(key)
})

const WUXING_SHENG = HEX_DATA.wuxing.sheng
const WUXING_KE = HEX_DATA.wuxing.ke

function normalizeNumber(num, maxVal) {
  const result = num % maxVal
  return result === 0 ? maxVal : result
}

function getTrigramInfo(num) {
  return HEX_DATA.trigrams[String(num)]
}

function getHexName(upperNum, lowerNum) {
  const key = `${upperNum}-${lowerNum}`
  const hexagram = HEX_DATA.hexagrams[key]
  return hexagram && hexagram.name ? hexagram.name : `${getTrigramInfo(upperNum).name}${getTrigramInfo(lowerNum).name}`
}

function analyzeRelation(ti, yong) {
  if (ti === yong) return '体用比和'
  if (WUXING_SHENG[ti] === yong) return '体生用'
  if (WUXING_SHENG[yong] === ti) return '用生体'
  if (WUXING_KE[ti] === yong) return '体克用'
  if (WUXING_KE[yong] === ti) return '用克体'
  return '关系持平'
}

function makeRelationParts(desc) {
  if (!desc) return [{ text: desc, bold: false }]
  const BOLD = ['克', '生', '比和']
  const cleaned = desc.replace(/\s+/g, '')
  if (cleaned === '体用比和') {
    return [{ text: '体用', bold: false }, { text: '比和', bold: true }]
  }
  for (var i = 0; i < BOLD.length; i++) {
    var word = BOLD[i]
    var idx = cleaned.indexOf(word)
    if (idx >= 0) {
      var parts = []
      if (idx > 0) parts.push({ text: cleaned.slice(0, idx), bold: false })
      parts.push({ text: word, bold: true })
      var after = cleaned.slice(idx + word.length)
      if (after) parts.push({ text: after, bold: false })
      return parts
    }
  }
  return [{ text: cleaned, bold: false }]
}

function normalizeRelationDesc(text) {
  if (!text) return text
  var cleaned = text.replace(/\s+/g, '')
  if (cleaned.indexOf('比和') >= 0) return '体用比和'
  if (cleaned.indexOf('体') >= 0 && cleaned.indexOf('用') >= 0 && cleaned.indexOf('生') >= 0) {
    return cleaned.indexOf('体') < cleaned.indexOf('用') ? '体生用' : '用生体'
  }
  if (cleaned.indexOf('体') >= 0 && cleaned.indexOf('用') >= 0 && cleaned.indexOf('克') >= 0) {
    return cleaned.indexOf('体') < cleaned.indexOf('用') ? '体克用' : '用克体'
  }
  return cleaned
}

function analyzeLingRelation(zhi, ti) {
  const zhiElement = ZHI_ELEMENTS[zhi]
  if (zhiElement === ti) return '比和'
  if (WUXING_SHENG[zhiElement] === ti) return '生体'
  if (WUXING_SHENG[ti] === zhiElement) return '体泄'
  if (WUXING_KE[zhiElement] === ti) return '克体'
  if (WUXING_KE[ti] === zhiElement) return '体克'
  return ''
}

function getRelationClass(rel) {
  if (rel === '生体' || rel === '比和') return 'ling-rel-strong'
  return 'ling-rel-soft'
}

function makeLingData(calendarInfo, hourGz, tiElement) {
  const pillars = [
    { label: '年', value: calendarInfo.gzYear },
    { label: '月', value: calendarInfo.gzMonth },
    { label: '日', value: calendarInfo.gzDay },
    { label: '时', value: hourGz },
  ]

  return pillars.map((item) => {
    const zhi = item.value.charAt(1)
    const element = ZHI_ELEMENTS[zhi]
    return {
      label: item.label,
      zhi,
      element,
      elementClass: elementLineClass(element),
      rel: analyzeLingRelation(zhi, tiElement),
    }
  })
}

function makeLines(yaoLines, changeYao, tiPos, upper, lower) {
  const lines = []

  for (let index = 5; index >= 0; index -= 1) {
    let roleLabel = ''
    if (index === 4) roleLabel = tiPos === 'upper' ? '体' : '用'
    if (index === 1) roleLabel = tiPos === 'lower' ? '体' : '用'
    const trigram = index >= 3 ? upper : lower

    lines.push({
      key: `line-${index}`,
      isYang: yaoLines[index] === 1,
      isChanging: changeYao === index + 1,
      roleLabel,
      lineClass: elementLineClass(trigram.element),
      sideName: trigram.name,
      sideElement: trigram.element,
      sideNature: trigram.nature,
    })
  }

  return lines
}

function makeCard(key, title, upperNum, lowerNum, yaoLines, changeYao, tiPos, calendarInfo, hourGz) {
  const upper = getTrigramInfo(upperNum)
  const lower = getTrigramInfo(lowerNum)
  const tiElement = tiPos === 'upper' ? upper.element : lower.element
  const yongElement = tiPos === 'upper' ? lower.element : upper.element

  return {
    key,
    title,
    name: getHexName(upperNum, lowerNum),
    upperNum,
    lowerNum,
    upperSymbol: upper.symbol,
    lowerSymbol: lower.symbol,
    upperName: upper.name,
    lowerName: lower.name,
    upperElement: upper.element,
    lowerElement: lower.element,
    upperNature: upper.nature,
    lowerNature: lower.nature,
    upperText: `${upper.name}${upper.element} ${upper.nature}`,
    lowerText: `${lower.name}${lower.element} ${lower.nature}`,
    tiElement,
    yongElement,
    relationDesc: analyzeRelation(tiElement, yongElement),
    relationParts: makeRelationParts(analyzeRelation(tiElement, yongElement)),
    relationClass: elementLineClass(tiElement),
    lines: makeLines(yaoLines, changeYao, tiPos, upper, lower),
    lingData: makeLingData(calendarInfo, hourGz, tiElement).map((item) =>
      Object.assign({}, item, { relClass: getRelationClass(item.rel) })
    ),
  }
}

function formatRelWithElements(desc, tiEl, yongEl) {
  if (desc === '体用比和') return `体(${tiEl})用(${yongEl})比和`
  return desc.replace('体', `体(${tiEl})`).replace('用', `用(${yongEl})`)
}

function formatLingRel(rel, zhi, zhiEl, tiEl) {
  switch (rel) {
    case '生体': return `${zhi}(${zhiEl})生体(${tiEl})`
    case '克体': return `${zhi}(${zhiEl})克体(${tiEl})`
    case '体泄': return `体(${tiEl})生${zhi}(${zhiEl})`
    case '体克': return `体(${tiEl})克${zhi}(${zhiEl})`
    case '比和': return `${zhi}(${zhiEl})比和体(${tiEl})`
    default:     return `${zhi}(${zhiEl}) ${rel}`
  }
}

function makeReport(result) {
  const lineLabels = ['上', '五', '四', '三', '二', '初']
  const ganzhiItems = result.ganzhiText ? result.ganzhiText.split(/\s+/) : []
  const reportGanzhi =
    ganzhiItems.length === 4
      ? `${ganzhiItems[0]}年 ${ganzhiItems[1]}月 ${ganzhiItems[2]}日 ${ganzhiItems[3]}时`
      : result.ganzhiText

  const noteHeader = result.note ? `【备注】：${result.note}\n--------------------------------------------------\n` : ''

  const sections = result.cards.map((card) => {
    const tiEl = card.tiElement || ''
    const yongEl = card.yongElement || ''
    const linesText = card.lines
      .map((line, index) => {
        const lineText = line.isYang ? '━━━━━━━━━━━━' : '━━━━━  ━━━━━'
        const mark = line.isChanging ? ' ●' : '  '
        const note = line.roleLabel ? `${line.roleLabel}卦：${line.sideElement}` : ''
        const row = `${lineLabels[index]}爻  ${lineText}${mark}    ${note}`
        return index === 2 ? row + '\n─────────────────────────' : row
      })
      .join('\n')
    const upperRole = card.lines[1] && card.lines[1].roleLabel ? `${card.lines[1].roleLabel}卦` : ''
    const lowerRole = card.lines[4] && card.lines[4].roleLabel ? `${card.lines[4].roleLabel}卦` : ''
    const upperRoleText = upperRole ? ` [${upperRole}：${card.upperElement}]` : ''
    const lowerRoleText = lowerRole ? ` [${lowerRole}：${card.lowerElement}]` : ''
    const ling = card.lingData
      .map((item) => `${item.label}令关系：${formatLingRel(item.rel, item.zhi, item.element, tiEl)}`)
      .join('\n')
    return [
      `[${card.title}：${card.name}]`,
      linesText,
      `上卦：${card.upperSymbol || ''} ${card.upperName}${card.upperNum}(${card.upperNature})${upperRoleText}`,
      `下卦：${card.lowerSymbol || ''} ${card.lowerName}${card.lowerNum}(${card.lowerNature})${lowerRoleText}`,
      `体用关系：${formatRelWithElements(card.relationDesc, tiEl, yongEl)}`,
      ling,
    ].join('\n')
  })

  const numsText = result.inputNums ? `数字：${result.inputNums.join(' ')}` : ''

  return [
    `${noteHeader}起卦时间：${result.timestamp}`,
    `四柱八字：${reportGanzhi}`,
    numsText,
    '--------------------------------------------------',
    sections.join('\n\n'),
    '--------------------------------------------------',
  ].join('\n')
}

function decorateResult(result) {
  if (!result) return result
  const next = Object.assign({}, result)
  if (!next.ganzhiParts && next.ganzhiText) {
    next.ganzhiParts = makeGanzhiParts(next.ganzhiText)
  }
  if (!next.historyPillars && next.ganzhiText) {
    next.historyPillars = next.ganzhiText.split(/\s+/).filter((item) => item)
  }
  if (next.historyPillars) {
    next.pillarParts = next.historyPillars.map((pillar) => makeGanzhiParts(pillar))
  }
  if (next.cards) {
    next.cards = next.cards.map((card) =>
      Object.assign({}, card, {
        relationDesc: normalizeRelationDesc(card.relationDesc),
        relationParts: makeRelationParts(normalizeRelationDesc(card.relationDesc)),
        lingData: (card.lingData || []).map((item) =>
          Object.assign({}, item, {
            elementClass: item.elementClass || elementLineClass(item.element),
          })
        ),
      })
    )
  }
  if (next.cards && next.cards.length && next.cards[0].lines) {
    next.reportText = makeReport(next)
  }
  return next
}

function performDivination(inputNumbers) {
  const now = new Date()
  const n1 = normalizeNumber(inputNumbers[0], 8)
  const n2 = normalizeNumber(inputNumbers[1], 8)
  const n3 = normalizeNumber(inputNumbers[2], 6)

  const currentHour = now.getHours()
  // 晚子时（23 点）的日柱由 getCalendarInfo 自己按次日计，这里不能再加一天
  const calendarInfo = getCalendarInfo(now)
  const hourIndex = currentHour === 23 ? 0 : Math.floor((currentHour + 1) / 2) % 12
  const hourGz = getHourGanZhi(calendarInfo.gzDay.charAt(0), hourIndex)
  const timestamp = `${formatDate(now)} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}:${String(now.getSeconds()).padStart(2, '0')}`
  const ganzhiText = `${calendarInfo.gzYear} ${calendarInfo.gzMonth} ${calendarInfo.gzDay} ${hourGz}`

  const benUpper = n1
  const benLower = n2
  const benUpperInfo = getTrigramInfo(benUpper)
  const benLowerInfo = getTrigramInfo(benLower)
  const benLines = benLowerInfo.yao.concat(benUpperInfo.yao)

  const bianLines = benLines.slice()
  bianLines[n3 - 1] = bianLines[n3 - 1] === 1 ? 0 : 1
  const bianLower = YAO_TO_NUM[bianLines.slice(0, 3).join('-')]
  const bianUpper = YAO_TO_NUM[bianLines.slice(3).join('-')]

  const huLowerLines = [benLines[1], benLines[2], benLines[3]]
  const huUpperLines = [benLines[2], benLines[3], benLines[4]]
  const huLower = YAO_TO_NUM[huLowerLines.join('-')]
  const huUpper = YAO_TO_NUM[huUpperLines.join('-')]
  const huLines = huLowerLines.concat(huUpperLines)

  const tiPos = n3 >= 4 ? 'lower' : 'upper'
  const cards = [
    makeCard('ben', '本卦', benUpper, benLower, benLines, n3, tiPos, calendarInfo, hourGz),
    makeCard('bian', '变卦', bianUpper, bianLower, bianLines, n3, tiPos, calendarInfo, hourGz),
    makeCard('hu', '互卦', huUpper, huLower, huLines, n3, tiPos, calendarInfo, hourGz),
  ]

  const result = {
    id: Date.now(),
    timestamp,
    ganzhiText,
    ganzhiParts: makeGanzhiParts(ganzhiText),
    historyPillars: ganzhiText.split(/\s+/),
    note: '',
    inputNums: [n1, n2, n3],
    reportText: '',
    cards,
  }

  result.reportText = makeReport(result)
  return result
}

function recalculateFromStored(storedItem) {
  const inputNums = storedItem.inputNums
  if (!inputNums || inputNums.length < 3) return decorateResult(storedItem)

  const n1 = normalizeNumber(inputNums[0], 8)
  const n2 = normalizeNumber(inputNums[1], 8)
  const n3 = normalizeNumber(inputNums[2], 6)

  const parts = (storedItem.ganzhiText || '').split(/\s+/).filter(Boolean)
  const calendarInfo = { gzYear: parts[0] || '', gzMonth: parts[1] || '', gzDay: parts[2] || '' }
  const hourGz = parts[3] || ''

  const benUpper = n1
  const benLower = n2
  const benUpperInfo = getTrigramInfo(benUpper)
  const benLowerInfo = getTrigramInfo(benLower)
  const benLines = benLowerInfo.yao.concat(benUpperInfo.yao)

  const bianLines = benLines.slice()
  bianLines[n3 - 1] = bianLines[n3 - 1] === 1 ? 0 : 1
  const bianLower = YAO_TO_NUM[bianLines.slice(0, 3).join('-')]
  const bianUpper = YAO_TO_NUM[bianLines.slice(3).join('-')]

  const huLowerLines = [benLines[1], benLines[2], benLines[3]]
  const huUpperLines = [benLines[2], benLines[3], benLines[4]]
  const huLower = YAO_TO_NUM[huLowerLines.join('-')]
  const huUpper = YAO_TO_NUM[huUpperLines.join('-')]
  const huLines = huLowerLines.concat(huUpperLines)

  const tiPos = n3 >= 4 ? 'lower' : 'upper'
  const cards = [
    makeCard('ben', '本卦', benUpper, benLower, benLines, n3, tiPos, calendarInfo, hourGz),
    makeCard('bian', '变卦', bianUpper, bianLower, bianLines, n3, tiPos, calendarInfo, hourGz),
    makeCard('hu', '互卦', huUpper, huLower, huLines, n3, tiPos, calendarInfo, hourGz),
  ]

  const result = Object.assign({}, storedItem, {
    inputNums: [n1, n2, n3],
    ganzhiParts: makeGanzhiParts(storedItem.ganzhiText || ''),
    historyPillars: (storedItem.ganzhiText || '').split(/\s+/).filter(Boolean),
    cards,
  })
  result.pillarParts = result.historyPillars.map((pillar) => makeGanzhiParts(pillar))
  result.reportText = makeReport(result)
  return result
}

module.exports = {
  performDivination,
  decorateResult,
  recalculateFromStored,
  makeGanzhiParts,
}

}
defs["utils/liuren.js"] = function (module, exports, require) {
// miniprogram/utils/liuren.js
// 六壬排盘逻辑 — JavaScript port of web/logic_liuren.py

const calendarUtils = require('./calendar.js')

const GAN = ['甲', '乙', '丙', '丁', '戊', '己', '庚', '辛', '壬', '癸']
const ZHI = ['子', '丑', '寅', '卯', '辰', '巳', '午', '未', '申', '酉', '戌', '亥']

const WUXING = {
  甲: '木', 乙: '木', 丙: '火', 丁: '火', 戊: '土', 己: '土', 庚: '金', 辛: '金', 壬: '水', 癸: '水',
  子: '水', 丑: '土', 寅: '木', 卯: '木', 辰: '土', 巳: '火', 午: '火', 未: '土', 申: '金', 酉: '金', 戌: '土', 亥: '水',
}
const SHENG = { 木: '火', 火: '土', 土: '金', 金: '水', 水: '木' }
const KE = { 木: '土', 土: '水', 水: '火', 火: '金', 金: '木' }

const GAN_HOME = {
  甲: '寅', 乙: '辰', 丙: '巳', 丁: '未', 戊: '巳',
  己: '未', 庚: '申', 辛: '戌', 壬: '亥', 癸: '丑',
}
const NOBLE_DAY_NIGHT = {
  甲: ['丑', '未'], 戊: ['丑', '未'], 庚: ['丑', '未'],
  乙: ['子', '申'], 己: ['子', '申'],
  丙: ['亥', '酉'], 丁: ['亥', '酉'],
  壬: ['巳', '卯'], 癸: ['巳', '卯'],
  辛: ['午', '寅'],
}
const GENERAL_ORDER = ['贵', '蛇', '雀', '合', '勾', '龙', '空', '虎', '常', '玄', '阴', '后']
const XUN_EMPTY = {
  甲子: '戌亥', 甲戌: '申酉', 甲申: '午未', 甲午: '辰巳', 甲辰: '寅卯', 甲寅: '子丑',
}
const YANG = { 甲: 1, 丙: 1, 戊: 1, 庚: 1, 壬: 1, 子: 1, 寅: 1, 辰: 1, 午: 1, 申: 1, 戌: 1 }
const XING = {
  寅: '巳', 巳: '申', 申: '寅',
  丑: '戌', 戌: '未', 未: '丑',
  子: '卯', 卯: '子',
  辰: '辰', 午: '午', 酉: '酉', 亥: '亥',
}
const CHONG = {
  子: '午', 丑: '未', 寅: '申', 卯: '酉', 辰: '戌', 巳: '亥',
  午: '子', 未: '丑', 申: '寅', 酉: '卯', 戌: '辰', 亥: '巳',
}
const GAN_HE = { 甲: '己', 己: '甲', 乙: '庚', 庚: '乙', 丙: '辛', 辛: '丙', 丁: '壬', 壬: '丁', 戊: '癸', 癸: '戊' }
const SANHE_NEXT = {
  申: '子', 子: '辰', 辰: '申',
  亥: '卯', 卯: '未', 未: '亥',
  寅: '午', 午: '戌', 戌: '寅',
  巳: '酉', 酉: '丑', 丑: '巳',
}
const YIMA = {
  申: '寅', 子: '寅', 辰: '寅',
  寅: '申', 午: '申', 戌: '申',
  亥: '巳', 卯: '巳', 未: '巳',
  巳: '亥', 酉: '亥', 丑: '亥',
}
const MENG = { 寅: 1, 申: 1, 巳: 1, 亥: 1 }
const ZHONG = { 子: 1, 午: 1, 卯: 1, 酉: 1 }
const REL = { same: '兄弟', resource: '父母', output: '子孙', wealth: '妻财', officer: '官鬼' }

// 月将 by solar longitude sector (0=春分sector, 1=谷雨sector, ...)
const MG_BY_SECTOR = ['戌', '酉', '申', '未', '午', '巳', '辰', '卯', '寅', '丑', '子', '亥']
const ZQ_NAMES = ['春分', '谷雨', '小满', '夏至', '大暑', '处暑', '秋分', '霜降', '小雪', '冬至', '大寒', '雨水']

const ELEMENT_CLASS = { 木: 'wood', 火: 'fire', 土: 'earth', 金: 'gold', 水: 'water' }

// ── Helpers ───────────────────────────────────────────────────────────────────

function pad(n) { return String(n).padStart(2, '0') }

function zhiAt(idx) { return ZHI[((idx % 12) + 12) % 12] }

// ── True Solar Time ───────────────────────────────────────────────────────────

// 时间都是钟面时间的 wall 毫秒数（见 calendar.js），不经过设备时区
function equationOfTime(wall) {
  // Spencer 1971 approximation, returns minutes
  const start = Date.UTC(new Date(wall).getUTCFullYear(), 0, 0)
  const doy = Math.floor((wall - start) / 86400000) // day of year (1-based)
  const B = Math.PI / 180 * (360 / 365) * (doy - 81)
  return 9.87 * Math.sin(2 * B) - 7.53 * Math.cos(B) - 1.5 * Math.sin(B)
}

function toTrueSolarTime(wall, longitude) {
  const corrMin = (longitude - 120.0) * 4.0 + equationOfTime(wall)
  return Math.trunc(wall + corrMin * 60000)
}

// ── Solar Longitude & Month General ──────────────────────────────────────────

function getSolarLongitude(wall) {
  // Simplified VSOP87, accurate to ~0.5°; wall is Beijing clock time
  const d = (wall - 8 * 3600000 - Date.UTC(2000, 0, 1, 12, 0, 0)) / 86400000
  const L = (280.46646 + 0.9856474 * d) % 360
  const M = ((357.52911 + 0.98560028 * d) % 360) * Math.PI / 180
  const C = 1.914602 * Math.sin(M) + 0.019993 * Math.sin(2 * M) + 0.000289 * Math.sin(3 * M)
  return ((L + C) % 360 + 360) % 360
}

function getMonthGeneralInfo(date) {
  const info = calendarUtils.getZhongqiInfo ? calendarUtils.getZhongqiInfo(date) : null
  const idx = info ? info.sectorIndex : Math.floor(getSolarLongitude(date) / 30)
  return {
    monthGeneral: MG_BY_SECTOR[idx],
    prevQiName: info ? info.prevText : ZQ_NAMES[idx],
    nextQiName: info ? info.nextText : ZQ_NAMES[(idx + 1) % 12],
  }
}

// ── Hour Branch ───────────────────────────────────────────────────────────────

function getHourBranch(wall) {
  const h = new Date(wall).getUTCHours()
  if (h === 23) return '子'
  return ZHI[Math.floor((h + 1) / 2) % 12]
}

// ── Xun & Hidden Stems ────────────────────────────────────────────────────────

function getXun(dayGz) {
  const gi = GAN.indexOf(dayGz[0])
  const zi = ZHI.indexOf(dayGz[1])
  return '甲' + zhiAt(zi - gi)
}

function getHiddenStems(dayGz) {
  const xun = getXun(dayGz)
  const startZi = ZHI.indexOf(xun[1])
  return GAN.map((gan, i) => ({
    stem: gan,
    branch: zhiAt(startZi + i),
    ganzhi: gan + zhiAt(startZi + i),
  }))
}

function stemForBranch(branch, hiddenStems) {
  const item = hiddenStems.find(h => h.branch === branch)
  return item ? item.stem : ''
}

// ── Heaven-Earth Plate ────────────────────────────────────────────────────────

function buildPlate(monthGeneral, hourBranch) {
  const gi = ZHI.indexOf(monthGeneral)
  const hi = ZHI.indexOf(hourBranch)
  const plate = []
  const skyByEarth = {}
  const earthBySky = {}
  for (let i = 0; i < 12; i++) {
    const earth = ZHI[i]
    const sky = zhiAt(gi + i - hi)
    skyByEarth[earth] = sky
    earthBySky[sky] = earth
    plate.push({ earth, heaven: sky, heavenElement: WUXING[sky] })
  }
  return { plate, skyByEarth, earthBySky }
}

// ── Relations ─────────────────────────────────────────────────────────────────

function relation(upper, lower) {
  const ue = WUXING[upper], le = WUXING[lower]
  if (ue === le) return '比和'
  if (KE[ue] === le) return '上克下'
  if (KE[le] === ue) return '下贼上'
  if (SHENG[ue] === le) return '上生下'
  if (SHENG[le] === ue) return '下生上'
  return '无涉'
}

function relativeToDay(dayGan, branch) {
  const de = WUXING[dayGan], be = WUXING[branch]
  if (de === be) return REL.same
  if (SHENG[be] === de) return REL.resource
  if (SHENG[de] === be) return REL.output
  if (KE[de] === be) return REL.wealth
  if (KE[be] === de) return REL.officer
  return ''
}

// ── Four Lessons ──────────────────────────────────────────────────────────────

function buildFourLessons(dayGz, skyByEarth) {
  const dg = dayGz[0], db = dayGz[1]
  const fL = GAN_HOME[dg], fU = skyByEarth[fL]
  const sL = fU, sU = skyByEarth[sL]
  const tL = db, tU = skyByEarth[tL]
  const foL = tU, foU = skyByEarth[foL]
  return [
    ['壹', dg, fL, fU], ['貳', fU, sL, sU],
    ['叁', db, tL, tU], ['肆', tU, foL, foU],
  ].map(([name, subject, lower, upper]) => ({
    name, subject, lower, upper,
    lowerElement: WUXING[subject], upperElement: WUXING[upper],
    upperElementClass: ELEMENT_CLASS[WUXING[upper]],
    relation: relation(upper, subject),
  }))
}

// ── Three Transmissions ───────────────────────────────────────────────────────

// 涉害：从发用之神所临的地盘起，逐位数到它的本家，地支和寄在该位的天干都算：
// 上克下数它克了几位，下贼上数它受了几位克。与《六壬大全》七百二十课所载三传一致。
const STEMS_AT_BRANCH = {}
Object.keys(GAN_HOME).forEach((g) => { (STEMS_AT_BRANCH[GAN_HOME[g]] = STEMS_AT_BRANCH[GAN_HOME[g]] || []).push(g) })

function harmDepth(course, relationName) {
  const start = ZHI.indexOf(course.lower)
  const end = ZHI.indexOf(course.upper)
  const steps = (end - start + 12) % 12
  const upperEl = WUXING[course.upper]
  const hit = relationName === '上克下' ? (el) => KE[upperEl] === el : (el) => KE[el] === upperEl
  let total = 0
  for (let i = 0; i <= steps; i++) {
    const earth = zhiAt(start + i)
    if (hit(WUXING[earth])) total += 1
    ;(STEMS_AT_BRANCH[earth] || []).forEach((g) => { if (hit(WUXING[g])) total += 1 })
  }
  return total
}

function selectByShehai(candidates, relationName, dayIsYang) {
  const scored = candidates.map(c => ({ c, depth: harmDepth(c, relationName) }))
  const maxDepth = Math.max(...scored.map(x => x.depth))
  let pool = scored.filter(x => x.depth === maxDepth).map(x => x.c)
  const meng = pool.filter(c => MENG[c.lower])
  if (meng.length) {
    pool = meng
  } else {
    const zhong = pool.filter(c => ZHONG[c.lower])
    if (zhong.length) pool = zhong
  }
  const preferredNames = dayIsYang ? ['壹', '貳'] : ['叁', '肆']
  const preferred = pool.filter(c => preferredNames.indexOf(c.name) >= 0)
  return (preferred.length ? preferred[0] : pool[0]).upper
}

function selectInitial(candidates, dayIsYang, relationName) {
  if (candidates.length === 1) return { initial: candidates[0].upper, extra: null }
  const matched = candidates.filter(c => Boolean(YANG[c.upper]) === dayIsYang)
  if (matched.length === 1) return { initial: matched[0].upper, extra: '比用' }
  const pool = matched.length ? matched : candidates
  return { initial: selectByShehai(pool, relationName, dayIsYang), extra: '涉害' }
}

function buildThreeTransmissions(dayGz, lessons, skyByEarth, hiddenStems) {
  const dg = dayGz[0], db = dayGz[1], dayIsYang = Boolean(YANG[dg])
  const courseTypes = []
  const fuyin = ZHI.every(z => skyByEarth[z] === z)
  const fanyin = ZHI.every(z => skyByEarth[z] === CHONG[z])
  const earthBySky = {}
  Object.keys(skyByEarth).forEach(earth => { earthBySky[skyByEarth[earth]] = earth })

  let initial, middle, final
  if (fuyin) {
    courseTypes.push('伏吟课')
    const beike = lessons.filter(c => c.relation === '下贼上')
    const yuanshou = lessons.filter(c => c.relation === '上克下')
    if (beike.length) {
      const r = selectInitial(beike, dayIsYang, '下贼上')
      initial = r.initial; if (r.extra) courseTypes.push(r.extra)
    } else if (yuanshou.length) {
      const r = selectInitial(yuanshou, dayIsYang, '上克下')
      initial = r.initial; if (r.extra) courseTypes.push(r.extra)
    } else {
      initial = dayIsYang ? GAN_HOME[dg] : db
    }
    // 中传取初传所刑；初传自刑时取另一边的上神（初传是干上神就取支上神，反之取干上神）。
    // 末传取中传所刑；中传自刑，或刑回初传（如子卯相刑），取中传之冲
    middle = XING[initial] !== undefined ? XING[initial] : initial
    if (middle === initial) middle = initial === lessons[0].upper ? lessons[2].upper : lessons[0].upper
    final = XING[middle] !== undefined ? XING[middle] : middle
    if (final === middle || final === initial) final = CHONG[middle]
    if (middle === initial) courseTypes.push('自任')
  } else if (fanyin) {
    courseTypes.push('返吟课')
    const beike = lessons.filter(c => c.relation === '下贼上')
    const yuanshou = lessons.filter(c => c.relation === '上克下')
    if (beike.length) {
      const r = selectInitial(beike, dayIsYang, '下贼上')
      initial = r.initial; if (r.extra) courseTypes.push(r.extra)
      middle = CHONG[initial]
      final = CHONG[middle]
    } else if (yuanshou.length) {
      const r = selectInitial(yuanshou, dayIsYang, '上克下')
      initial = r.initial; if (r.extra) courseTypes.push(r.extra)
      middle = CHONG[initial]
      final = CHONG[middle]
    } else {
      initial = YIMA[db]
      middle = lessons[2].upper
      final = lessons[0].upper
      courseTypes.push('井栏射')
    }
  } else {
    const beike = lessons.filter(c => c.relation === '下贼上')
    const yuanshou = lessons.filter(c => c.relation === '上克下')
    if (beike.length) {
      courseTypes.push('重审课')
      const r = selectInitial(beike, dayIsYang, '下贼上')
      initial = r.initial; if (r.extra) courseTypes.push(r.extra)
    } else if (yuanshou.length) {
      courseTypes.push('元首课')
      const r = selectInitial(yuanshou, dayIsYang, '上克下')
      initial = r.initial; if (r.extra) courseTypes.push(r.extra)
    } else if (GAN_HOME[dg] === db) {
      // 干支同位（甲寅、庚申、丁未、己未、癸丑）四课只有两课，无克时取八专，先于遥克：
      // 阳日干上神顺数三位、阴日第四课上神逆数三位为初传，中末都取干上神
      courseTypes.push('八专课')
      initial = dayIsYang ? zhiAt(ZHI.indexOf(lessons[0].upper) + 2) : zhiAt(ZHI.indexOf(lessons[3].upper) - 2)
      middle = lessons[0].upper
      final = lessons[0].upper
    } else {
      const de = WUXING[dg]
      const haoshi = lessons.filter(c => KE[de] === WUXING[c.upper])
      const hushi = lessons.filter(c => KE[WUXING[c.upper]] === de)
      if (haoshi.length || hushi.length) {
        courseTypes.push('遥克课')
        if (hushi.length) {
          courseTypes.push('蒿矢')
          const r = selectInitial(hushi, dayIsYang, '上克下')
          initial = r.initial; if (r.extra) courseTypes.push(r.extra)
        } else {
          courseTypes.push('弹射')
          const r = selectInitial(haoshi, dayIsYang, '下贼上')
          initial = r.initial; if (r.extra) courseTypes.push(r.extra)
        }
      } else {
        const distinct = {}
        lessons.forEach(c => { distinct[`${c.lower}-${c.upper}`] = true })
        const count = Object.keys(distinct).length
        if (count === 4) {
          courseTypes.push('昴星课')
          initial = dayIsYang ? skyByEarth.酉 : earthBySky.酉
          middle = dayIsYang ? lessons[2].upper : lessons[0].upper
          final = dayIsYang ? lessons[0].upper : lessons[2].upper
        } else if (count === 3) {
          courseTypes.push('别责课')
          initial = dayIsYang ? skyByEarth[GAN_HOME[GAN_HE[dg]]] : SANHE_NEXT[db]
          middle = lessons[0].upper
          final = lessons[0].upper
        } else {
          courseTypes.push('八专课')
          initial = dayIsYang ? zhiAt(ZHI.indexOf(lessons[0].upper) + 2) : zhiAt(ZHI.indexOf(lessons[3].upper) - 2)
          middle = lessons[0].upper
          final = lessons[0].upper
        }
      }
    }
    if (courseTypes.indexOf('昴星课') < 0 && courseTypes.indexOf('别责课') < 0 && courseTypes.indexOf('八专课') < 0) {
      middle = skyByEarth[initial]
      final = skyByEarth[middle]
    }
  }

  const transmissions = [initial, middle, final].map((branch, i) => {
    const stem = stemForBranch(branch, hiddenStems)
    return {
      name: ['初传', '中传', '末传'][i],
      branch, stem,
      ganzhi: stem ? stem + branch : branch,
      display: stem ? stem + branch : '空' + branch,
      isEmpty: !stem,
      element: WUXING[branch],
      sixRelative: relativeToDay(dg, branch),
    }
  })
  return { transmissions, courseTypes }
}

// ── Twelve Generals ───────────────────────────────────────────────────────────

function buildTwelveGenerals(dayGan, hourBranch, skyByEarth, forcedMode) {
  const isDay = forcedMode === 'day' ? true
              : forcedMode === 'night' ? false
              : ['卯', '辰', '巳', '午', '未', '申'].indexOf(hourBranch) >= 0
  const nobleBranch = NOBLE_DAY_NIGHT[dayGan][isDay ? 0 : 1]
  const nobleEarth = ZHI.find(e => skyByEarth[e] === nobleBranch) || nobleBranch
  const reverse = ['巳', '午', '未', '申', '酉', '戌'].indexOf(nobleEarth) >= 0
  const ni = ZHI.indexOf(nobleBranch)
  const generalsBySky = {}
  for (let offset = 0; offset < 12; offset++) {
    const sky = zhiAt(reverse ? ni - offset : ni + offset)
    generalsBySky[sky] = GENERAL_ORDER[offset]
  }
  const generals = ZHI.map(earth => ({
    earth, heaven: skyByEarth[earth],
    heavenElement: WUXING[skyByEarth[earth]],
    heavenElementClass: ELEMENT_CLASS[WUXING[skyByEarth[earth]]],
    general: generalsBySky[skyByEarth[earth]] || '',
  }))
  return { generals, mode: isDay ? '昼贵' : '夜贵', nobleBranch, nobleEarth, generalsBySky }
}

// ── Report Text ───────────────────────────────────────────────────────────────

function buildReport(data) {
  const { calendar: cal, liuren: lr, question } = data
  const hidden = lr.hiddenStems.map(h => `${h.stem}遁${h.branch}`).join('　')
  const plateLine = lr.heavenEarthPlate.map(x => `${x.heaven}临${x.earth}`).join('　')
  const genLine = lr.twelveGenerals.map(x => `${x.earth}宫：${x.general}将，天盘${x.heaven}`).join('　')
  const lessonLines = lr.fourLessons.map(x =>
    `${x.name}：${x.subject}上${x.upper}，${x.relation}，下类=${x.lowerElement}，上神=${x.upperElement}`
  )
  const transLines = lr.threeTransmissions.map(x =>
    `${x.name}：${x.sixRelative} ${x.display} ${x.general || ''}，地盘=${x.earth || x.branch}，五行=${x.element}${x.isEmpty ? '，旬空' : ''}`
  )
  return [
    '【六壬排盘】',
    `问事：${question || '[暂未填写]'}`,
    `北京时间：${cal.solar}`,
    `真太阳时：${cal.trueSolarTime ? cal.trueSolarTime + '　东经' + cal.longitude.toFixed(2) + '°' : '无法获取'}`,
    '',
    '【时间信息】',
    `农历：${cal.lunar}`,
    `干支：${cal.ganzhi}`,
    `中气：${cal.jieqiPrev}；${cal.jieqiNext}`,
    '',
    '【起课信息】',
    `月将：${lr.monthGeneral}将（${lr.monthGeneralOverridden ? '覆写' : '系统'}）`,
    `占时：${lr.hourBranch}时${lr.hourBranchOverridden ? '（覆写）' : ''}`,
    `贵人：${lr.nobleMode} ${lr.nobleBranch}，落地盘 ${lr.nobleEarth}${lr.nobleModeOverridden ? '（覆写）' : ''}`,
    `旬遁：${lr.xun}旬，${lr.emptyBranches}空`,
    `日柱遁干：${hidden}`,
    `课体：${lr.courseTypes.length ? lr.courseTypes.join('、') : '未识别'}`,
    '',
    '【天地盘】',
    '天盘/地盘：' + plateLine,
    '',
    '【十二天将】',
    genLine,
    '',
    '【四课】',
    ...lessonLines,
    '',
    '【三传】',
    ...transLines,
  ].join('\n')
}

// ── Main Entry ────────────────────────────────────────────────────────────────

function performLiuren(params) {
  const { dateStr, timeStr, question, longitude, overrides = {} } = params
  // dateStr: 'YYYY-MM-DD', timeStr: 'HH:MM[:SS]'
  const [yr, mo, dy] = dateStr.split('-').map(Number)
  const [hr, mi, se = 0] = timeStr.split(':').map(Number)
  const dtInput = Date.UTC(yr, mo - 1, dy, hr, mi, se)

  // Apply TST if longitude provided
  let dt = dtInput
  let trueSolarTimeStr = null
  if (longitude != null) {
    dt = toTrueSolarTime(dtInput, longitude)
    const p = calendarUtils.wallParts(dt)
    trueSolarTimeStr = `${p.y}-${pad(p.m)}-${pad(p.d)} ${pad(p.h)}:${pad(p.mi)}:${pad(p.s)}`
  }

  const hourBranch = overrides.hourBranch || getHourBranch(dt)

  // Calendar info from TST date/time; keep seconds so jieqi boundaries are precise.
  const calInfo = calendarUtils.getCalendarInfo(dt)
  const dayGz = calInfo.gzDay
  const hourIdx = ZHI.indexOf(hourBranch)
  const hourGz = calendarUtils.getHourGanZhi(dayGz[0], hourIdx)

  // Month general
  const mgInfo = getMonthGeneralInfo(dt)
  const monthGeneral = overrides.monthGeneral || mgInfo.monthGeneral

  // Compute plate, lessons, transmissions, generals
  const hiddenStems = getHiddenStems(dayGz)
  const xun = getXun(dayGz)
  const { plate, skyByEarth, earthBySky } = buildPlate(monthGeneral, hourBranch)
  const fourLessons = buildFourLessons(dayGz, skyByEarth)
  const { transmissions, courseTypes } = buildThreeTransmissions(dayGz, fourLessons, skyByEarth, hiddenStems)
  const { generals, mode, nobleBranch, nobleEarth, generalsBySky } = buildTwelveGenerals(dayGz[0], hourBranch, skyByEarth, overrides.nobleMode || null)

  // Attach generals and earth to lessons and transmissions
  for (const lesson of fourLessons) {
    lesson.general = generalsBySky[lesson.upper] || ''
  }
  for (const t of transmissions) {
    t.general = generalsBySky[t.branch] || ''
    t.earth = earthBySky[t.branch] || t.branch
  }

  const solarStr = `${yr}-${pad(mo)}-${pad(dy)} ${pad(hr)}:${pad(mi)}:${pad(se)}`
  const lunarStr = `${calInfo.lunar} ${hourBranch}时`
  const ganzhiStr = `${calInfo.gzYear}年 ${calInfo.gzMonth}月 ${dayGz}日 ${hourGz}时`

  const data = {
    question: (question || '').trim(),
    calendar: {
      solar: solarStr,
      trueSolarTime: trueSolarTimeStr,
      longitude: longitude != null ? Math.round(longitude * 100) / 100 : null,
      lunar: lunarStr,
      jieqiPrev: mgInfo.prevQiName,
      jieqiNext: mgInfo.nextQiName,
      ganzhi: ganzhiStr,
    },
    liuren: {
      monthGeneral,
      monthGeneralOverridden: Boolean(overrides.monthGeneral),
      hourBranch,
      hourBranchOverridden: Boolean(overrides.hourBranch),
      nobleMode: mode,
      nobleModeOverridden: Boolean(overrides.nobleMode),
      nobleBranch,
      nobleEarth,
      xun,
      emptyBranches: XUN_EMPTY[xun] || '',
      hiddenStems,
      heavenEarthPlate: plate,
      fourLessons,
      threeTransmissions: transmissions,
      twelveGenerals: generals,
      courseTypes,
    },
  }
  data.reportText = buildReport(data)
  return data
}

module.exports = { performLiuren }

}
defs["pages/index/ui.wxs"] = function (module, exports, require) {
// 只做展示用的小换算，避免为了显示格式在 JS 里多存一份数据

var ELEMENT_CLASS = { '金': 'gz-gold', '木': 'gz-wood', '水': 'gz-water', '火': 'gz-fire', '土': 'gz-earth' }

function tabIndex(tab) {
  if (tab === 'history') return 1
  if (tab === 'calendar') return 2
  if (tab === 'help') return 3
  return 0
}

function pillarLabel(i) {
  return ['年', '月', '日', '时'][i] || ''
}

function elClass(element) {
  return ELEMENT_CLASS[element] || 'gz-plain'
}

// 这里不用正则：WXS 对正则的支持和 JS 不完全一致，日期时间都按固定位置截取
// 日期 "YYYY-MM-DD"、时间 "HH:MM:SS"、时间戳 "YYYY-MM-DD HH:MM[:SS]"

function num(text) {
  return parseInt(text, 10)
}

function longDate(dateStr) {
  var t = dateStr ? '' + dateStr : ''
  if (t.length < 10) return ''
  return t.substring(0, 4) + '年' + num(t.substring(5, 7)) + '月' + num(t.substring(8, 10)) + '日'
}

function hm(timeStr) {
  var t = timeStr ? '' + timeStr : ''
  if (t.length < 5) return '--:--'
  return t.substring(0, 5)
}

// 往昔列表右上角的时间：M月D日 HH:MM
function shortStamp(text) {
  var t = text ? '' + text : ''
  if (t.length < 16) return t
  return num(t.substring(5, 7)) + '月' + num(t.substring(8, 10)) + '日 ' + t.substring(11, 16)
}

// 节气文字 "霜降 2026-10-23 17:37" → "10.23 17:37"
function termShort(text) {
  var t = text ? '' + text : ''
  var i = t.indexOf(' ')
  if (i < 0) return ''
  var stamp = t.substring(i + 1)
  if (stamp.length < 16) return ''
  return num(stamp.substring(5, 7)) + '.' + num(stamp.substring(8, 10)) + ' ' + stamp.substring(11, 16)
}

function termName(text) {
  var t = text ? '' + text : ''
  var i = t.indexOf(' ')
  return i < 0 ? t : t.substring(0, i)
}

function liurenNote(locating, longitudeText, attempted) {
  if (locating) return '定位中…'
  if (longitudeText) return '东经 ' + longitudeText + '°'
  if (attempted) return '未能定位，将使用北京时间'
  return '按所在经度校正时间'
}

function calendarNote(locating, tst, longitude) {
  if (locating) return '定位中…'
  if (tst) return longitude != null ? tst + ' · 东经 ' + longitude.toFixed(2) + '°' : tst
  return '北京时间 · 按所在经度换算'
}

function advLabel(index, options, suffix) {
  if (!index) return '系统'
  return options[index] + suffix
}

function matches(item, filter) {
  if (filter === 'all') return true
  return (item.type === 'liuren') === (filter === 'liuren')
}

function countMatching(items, filter) {
  var n = 0
  for (var i = 0; i < items.length; i++) if (matches(items[i], filter)) n++
  return n
}

// 当前主题色（深色模式取深色版本），给开关这类只能在属性里写颜色的原生组件用
function accentHex(options, id, isDark) {
  for (var i = 0; i < options.length; i++) {
    if (options[i].id === id) return isDark ? options[i].dark : options[i].light
  }
  return isDark ? '#F2F1EE' : '#121211'
}

module.exports = {
  accentHex: accentHex,
  tabIndex: tabIndex,
  elClass: elClass,
  pillarLabel: pillarLabel,
  longDate: longDate,
  hm: hm,
  shortStamp: shortStamp,
  termShort: termShort,
  termName: termName,
  liurenNote: liurenNote,
  calendarNote: calendarNote,
  advLabel: advLabel,
  matches: matches,
  countMatching: countMatching,
}

}
